import{z as l,x as o,o as B,c as d,q as n,j as r,D as e,d as a,s as t,S as s,b as A}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"做市风控与限额","description":"","frontmatter":{"title":"做市风控与限额","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/mm-risk-limits.md","filePath":"quant/mm-risk-limits.md","lastUpdated":1791063341000}'),m={name:"quant/mm-risk-limits.md"};function p(D,E,h,c,u,C){const i=o("Mermaid");return B(),d("div",null,[E[2]||(E[2]=n('<h1 id="做市风控与限额" tabindex="-1">做市风控与限额 <a class="header-anchor" href="#做市风控与限额" aria-label="Permalink to &quot;做市风控与限额&quot;">​</a></h1><div class="epigraph"><p>限额要活在两个地方：报价模型的边界条件里，让策略自己绕开它；模型外的风控引擎里，防的是策略自己出错的那天。</p><footer>—— 据 Guéant, Lehalle and Fernandez-Tapia, 2013；Harris, Trading and Exchanges, 2003 整理</footer></div><p><a href="/quant/mm-toxicity-online">上一课</a>让引擎知道何时收手；收手的动作需要授权边界，这就是限额。限额不是一行「最大库存」：它是层级化、分维度、软硬两级活的对象。本课写限额的清单、两层部署与失败模式。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>维度上，库存只是其一：库存（名义与按 \\(\\sigma\\) 折算的风险单位）、对冲后净敞口、日内累计亏损与止损线、单笔与单档报价规模、偏移上限、消息与撤单速率、到期与集中度，各自要各自的上限。层级上，公司、交易台、策略、腿逐级收紧，子级限额之和可以大于父级——协方差给出的余量——但绝不小于自己的父级。缺口在部署：软硬怎么分工、与报价引擎什么接口、谁在什么时候拦谁。</p><h3 id="软硬两级" tabindex="-1">软硬两级 <a class="header-anchor" href="#软硬两级" aria-label="Permalink to &quot;软硬两级&quot;">​</a></h3><p>硬限额由独立风控引擎执行：预检拒单（超规模、超偏移的报价直接拒绝）、库存越界关一侧、止损线触发收回全部报价。硬限额的执行路径必须独立于策略代码——它防的正是策略本身的参数错误、代码回滚与数据异常。软限额只降参：靠近软限时自动加倍偏度、缩减规模，让策略在边界前减速而不是撞墙。</p><p><span class="marginnote">「软限额」像汽车的预警与减速带：靠近边界时策略自动降参（加倍偏度、缩规模），不用踩死刹车；「硬限额」像安全气囊加断油保护：由独立引擎直接拒单、关一侧、收回全部报价，不听策略解释。软的负责让你不撞墙，硬的负责撞了那天也活得下来。</span></p><p><span class="marginnote">库存限额要用风险单位而不是股数：把 \\(Q\\) 写成 \\(k\\sigma\\) 的函数，高波动日限额自动缩容。事后开会调额度要一个交易日，\\(k\\sigma\\) 随体制收缩只要一次行情——快了一个数量级。</span></p><p><span class="marginnote">数字实例：库存限额 \\(5000\\) 股按风险单位折算——平静日 \\(\\sigma=0.5\\%\\)，这批库存折 \\(25\\) 个单位；波动日 \\(\\sigma\\) 翻倍到 \\(1\\%\\)，同样 \\(5000\\) 股就占 \\(50\\) 个单位。没有人开会调额度，同样的股数在高波动日自动「更占额度」，仓位被市场自己压下来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>模型内的限额即 <a href="/quant/glft-market-making">GLFT</a> 的边界条件：越界一侧的成交强度置零，靠近限额时偏度非线性放大——这是报价自洽的部分，策略「知道」边界在哪。模型外的引擎是墙，不知道也不需要知道策略意图。接口只有三个动词：查询（当前用量）、预检（这笔报价可否）、强制（收回、锁单）。</p><p>变更走审批与配置发布，与<a href="/quant/research-sim-prod">研究、模拟、实盘隔离</a>同一套发布纪律：谁提的、谁批的、何时生效、影响哪些策略，全部留痕。保证金维度按<a href="/quant/margin-maintenance">维持保证金</a>的初始线与维持线分开预算——开仓能力与存续能力不是同一个比例，做市账与保证金账要并排盯。</p>',13)),(B(),r(s,null,{default:e(()=>[t(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20LIM%5B%22%E9%99%90%E9%A2%9D%E4%BD%93%E7%B3%BB%22%5D%20--%3E%20HARD%5B%22%E7%A1%AC%E9%99%90%E9%A2%9D%EF%BC%9A%E9%A3%8E%E6%8E%A7%E5%BC%95%E6%93%8E%22%5D%0A%20%20LIM%20--%3E%20SOFT%5B%22%E8%BD%AF%E9%99%90%E9%A2%9D%EF%BC%9A%E8%87%AA%E5%8A%A8%E9%99%8D%E5%8F%82%22%5D%0A%20%20HARD%20--%3E%20P1%5B%22%E9%A2%84%E6%A3%80%E6%8B%92%E5%8D%95%22%5D%0A%20%20HARD%20--%3E%20P2%5B%22%E8%B6%8A%E7%95%8C%E5%85%B3%E4%B8%80%E4%BE%A7%22%5D%0A%20%20HARD%20--%3E%20P3%5B%22%E6%AD%A2%E6%8D%9F%E6%94%B6%E5%9B%9E%E6%8A%A5%E4%BB%B7%22%5D%0A%20%20SOFT%20--%3E%20P4%5B%22%E5%81%8F%E5%BA%A6%E5%8A%A0%E5%80%8D%E3%80%81%E8%A7%84%E6%A8%A1%E7%BC%A9%E5%87%8F%22%5D%0A%20%20P1%20--%3E%20ENG%5B%22%E6%8A%A5%E4%BB%B7%E5%BC%95%E6%93%8E%22%5D%0A%20%20P2%20--%3E%20ENG%0A%20%20P3%20--%3E%20ENG%0A%20%20P4%20--%3E%20ENG%0A%20%20MODEL%5B%22%E6%A8%A1%E5%9E%8B%E8%BE%B9%E7%95%8C%E6%9D%A1%E4%BB%B6%EF%BC%9AGLFT%20%E8%B6%8A%E7%95%8C%E4%BE%A7%E5%BC%BA%E5%BA%A6%E7%BD%AE%E9%9B%B6%22%5D%20--%3E%20ENG%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[a("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,[a("两层不一致的失败模式各有一种。限额只在引擎、模型不知道：报价在边界反复撞墙，来回改价暴露队列与意图，成交与撤销都变成信号。限额只在模型、引擎没有：参数漂移或回滚事故那天，第一道也是最后一道防线消失——风控引擎存在的理由就是假设那天会来。速率限额有双重身份：既是风暴时的自我保护，设在自己撮合通道处理能力之下，风暴时丢的是报价机会而不是断线；也是合规对象，撤单率是交易所监控口径，见 "),A("a",{href:"/quant/cancel-rate"},"撤单速率"),a("。")],-1)),(B(),r(s,null,{default:e(()=>[t(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%8F%AA%E9%83%A8%E7%BD%B2%E6%A8%A1%E5%9E%8B%E5%86%85%E9%99%90%E9%A2%9D%22%5D%20--%3E%20A1%5B%22%E5%8F%82%E6%95%B0%E6%BC%82%E7%A7%BB%E6%88%96%E5%9B%9E%E6%BB%9A%E4%BA%8B%E6%95%85%E9%82%A3%E5%A4%A9%22%5D%0A%20%20A1%20--%3E%20A2%5B%22%E5%BC%95%E6%93%8E%E6%97%A0%E5%A2%99%E5%8F%AF%E6%8B%A6%EF%BC%9A%E7%AC%AC%E4%B8%80%E9%81%93%E4%B9%9F%E6%98%AF%E6%9C%80%E5%90%8E%E4%B8%80%E9%81%93%E9%98%B2%E7%BA%BF%E6%B6%88%E5%A4%B1%22%5D%0A%20%20B%5B%22%E5%8F%AA%E9%83%A8%E7%BD%B2%E9%A3%8E%E6%8E%A7%E5%BC%95%E6%93%8E%22%5D%20--%3E%20B1%5B%22%E6%A8%A1%E5%9E%8B%E4%B8%8D%E7%9F%A5%E9%81%93%E8%BE%B9%E7%95%8C%E5%9C%A8%E5%93%AA%22%5D%0A%20%20B1%20--%3E%20B2%5B%22%E6%8A%A5%E4%BB%B7%E5%8F%8D%E5%A4%8D%E6%92%9E%E5%A2%99%EF%BC%9A%E6%94%B9%E4%BB%B7%E6%9A%B4%E9%9C%B2%E9%98%9F%E5%88%97%E4%B8%8E%E6%84%8F%E5%9B%BE%22%5D%0A%20%20C%5B%22%E6%A8%A1%E5%9E%8B%E8%BE%B9%E7%95%8C%E6%9D%A1%E4%BB%B6%20%2B%20%E7%8B%AC%E7%AB%8B%E5%BC%95%E6%93%8E%EF%BC%8C%E4%B8%A4%E5%B1%82%E9%83%BD%E5%9C%A8%22%5D%20--%3E%20C1%5B%22%E7%AD%96%E7%95%A5%E8%87%AA%E6%B4%BD%E5%87%8F%E9%80%9F%EF%BC%8C%E4%BA%8B%E6%95%85%E5%8F%A6%E6%9C%89%E7%A1%AC%E5%A2%99%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=n('<p>限额与毒性检测的接缝在上一课已经埋好：检测器的高档动作（单侧停、全停）就是软限额的行为化表达；限额体系保证即使检测器整体失灵，账上还有一个不会说谎的上限。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>熔断与停牌时段限额的语义要预先定义：复开批次里库存怎么算、报价义务与限额谁优先，参考<a href="/quant/circuit-breaker-design">熔断设计</a>的复开口径。跨场所库存聚合有延迟，限额按保守口径就地计算，不等全局对账。限额是风险偏好不是模型参数：不进回测优化目标，否则优化器会把限额磨平——回测里从未触限的限额，多半是被目标函数驯化过的限额。跨品种的向量限额是下一课的起点。</p><p><span class="marginnote">常见误区：初学者容易把限额当成回测里可调的参数去「优化」它。优化器发现触限的路径亏钱，就会学着永远贴在限内，回测从此不再触限——不是策略变好了，是限额被目标函数磨平了。限额是风险偏好，是事前划下的死线，只能由人和审批流程改，不能交给优化目标。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>限额分维度与层级：库存、净敞口、亏损、规模、速率、集中度，逐级收紧。</li><li>硬限额在模型外的引擎里：预检、越界关侧、止损收回，路径独立于策略代码。</li><li>软限额自动降参，模型内限额由 GLFT 边界条件表达，策略自洽绕行。</li><li>两层缺一：只有引擎则报价撞墙，只有模型则事故无拦。</li><li>速率限额既是自保也是合规对象；变更留痕走发布纪律。</li><li>出处：Guéant, Lehalle and Fernandez-Tapia, <em>Mathematics and Financial Economics</em>, 2013；Harris, <em>Trading and Exchanges</em>, 2003；Brunnermeier and Pedersen, <em>Review of Financial Studies</em>, 2009 的保证金约束口径。</li></ul>',6))])}const _=l(m,[["render",p]]);export{f as __pageData,_ as default};
